window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c621420d06746c7c"]={"versions": [{"id": "FIG-c621420d06746c7c", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Systemisches Datenfluss- und Bereitstellungsdiagramm (End-to-End Packaging &amp; OTA Deployment Flow).\n</li><li><strong>Funktionale Einordnung:</strong> Spezifikation der AUTOSAR Adaptive Platform für <em>Update and Configuration Management</em> (UCM, Release R18-10). Es definiert die mehrstufige Lieferkette und den Verteilungsmechanismus von Software-Artefakten – von Multi-Vendor-Zulieferern über Tier-1-Integratoren und das OEM-Backend bis zur Zielarchitektur im Fahrzeug (Adaptive AUTOSAR, Classic AUTOSAR und Non-AUTOSAR/COTS).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Upstream-Entitäten (Lieferkette)</h5>\n<ul class=\"fig-list\"><li><strong>Vendor B / Vendor C:</strong> Bereitsteller nativer Artefakte (<code>Executable</code>, <code>Persistency</code>-Daten, <code>Configuration files</code>).\n</li><li><strong>Integrator (Tier-1):</strong> Führt Artefakte in einem Software Cluster (<code>SWCL</code>) zusammen.\n<ul class=\"fig-list\"><li><code>Packager</code>: Vom UCM-Entwickler bereitgestelltes Tooling zur Paketerstellung.\n</li><li><code>Integrator signing package for traceability</code>: Signiert das <code>Backend package</code> kryptografisch zur Absicherung der Zulieferkette.\n</li><li><code>Integrator repository</code>: Zwischenstation zur Übergabe an das OEM-Backend.\n</li></ul>\n</li><li><strong>Adaptive Autosar UCM developer (OEM, vendor):</strong> Spezifiziert/liefert das Packager-Werkzeug.\n</li><li><strong>EE System engineer (OEM):</strong> Triggert und parametriert die Kampagnen im Backend.\n</li></ul>\n<h5 class=\"fig-section-h5\">OEM-Backend-Infrastruktur</h5>\n<ul class=\"fig-list\"><li><strong>Software catalog:</strong> Zentrales Repository für aufgenommene <code>Backend packages</code> (Integrator A &amp; B); extrahiert <code>Software Package</code> und <code>SWCL Package manifest</code>.\n</li><li><strong>VIN database:</strong> Speichert Fahrzeugkonfigurationen, aktuellen Softwarestand (<em>As-Built / As-Maintained</em>) und architekturelle Kompatibilitätsmatrizen.\n</li><li><strong>Campaign orchestrator:</strong> Koordiniert Update-Kampagnen anhand von Architektur-, VIN- und Softwarelisten.\n</li><li><strong>Key manager:</strong> Verwaltet OEM-Root-Keys und Zertifikate zur Erzeugung der endgültigen Fahrzeugsignaturen.\n</li><li><strong>Vehicle packager:</strong> Erzeugt das aggregierte <code>Vehicle package</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Datenstrukturen &amp; Paket-Hierarchie</h5>\n<ul class=\"fig-list\"><li><strong>SWCL (Software Cluster):</strong> Kleinste unabhängig aktualisierbare funktionale Einheit in Adaptive AUTOSAR.\n</li><li><strong>Backend package:</strong> Vom Integrator signierte Zwischenstufe des Pakets.\n</li><li><strong>Software Package:</strong> Einzelnes ECU-/Cluster-Update inkl. Binaries, Daten und <code>SWCL Package manifest</code>.\n</li><li><strong>Vehicle package:</strong> Aggregierter Container für das Gesamtfahrzeug, bestehend aus:\n<ul class=\"fig-list\"><li>Mehreren <code>Software Packages</code> (A, B, ...) mit Executables, Data und Manifesten.\n</li><li><code>SWCL Package manifest</code>.\n</li><li><code>Vehicle Package manifest</code> (Gesamtkompatibilität und Installationsreihenfolge).\n</li><li><code>Signed container</code> mit übergeordneter <code>OEM signature</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">In-Vehicle Target-Architektur</h5>\n<ul class=\"fig-list\"><li><strong>Gateway / Telematics:</strong> Funkschnittstelle (<code>Internet ETSI</code> / Antenne) als OTA-Endpunkt.\n</li><li><strong>Zielknoten:</strong> Multi-ECU-Netzwerk mit <strong>Adaptive AUTOSAR</strong> (UCM-Host), <strong>Classic AUTOSAR</strong> (über UDS/Diagnostic-Adapter) und <strong>IVI / COTS (Non-AUTOSAR)</strong>.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Phase 1: Upstream-Paketierung und Backend-Ingest</h5>\n<ol class=\"fig-list\"><li><strong>Artefakt-Erstellung:</strong> Vendors liefern Executables, Konfigurations- und Persistenzdaten an den Integrator.\n</li><li><strong>SWCL-Bündelung:</strong> Der Integrator packt die Artefakte via <code>Packager</code> in ein <code>Backend package</code> und signiert dieses zur Gewährleistung der Traceability.\n</li><li><strong>Katalogisierung:</strong> Bereitstellung in Integrator-Repos (A, B) und Übernahme in den <code>Software catalog</code> des OEM.\n</li></ol>\n<h5 class=\"fig-section-h5\">Phase 2: Zustandsermittlung &amp; Kampagnen-Orchestrierung</h5>\n<ul class=\"fig-list\"><li><strong>Zustandsabgleich (zwei Modi dargestellt):</strong>\n<ul class=\"fig-list\"><li><em>Modus 1 (Vehicle-driven):</em> Fahrzeug sendet Versionsstatus mit Fahrgestellnummer an das Backend: <code>1. Q: These are my versions statuses + VIN</code>.\n</li><li><em>Modus 2 (Backend-driven / Query):</em> Abfrage des Soll-/Ist-Zustands über <code>2. Q: Or what are your versions?</code> bzw. <code>2. Q: Please upload versions list</code>, beantwortet mit <code>2. A: My last versions for your VIN</code>.\n</li></ul>\n</li><li><strong>Kompilierung:</strong> Der <code>Campaign orchestrator</code> gleicht die VIN-Datenbank mit dem <code>Software catalog</code> ab. Der <code>Vehicle packager</code> assembliert die erforderlichen Software-Pakete und signiert den Gesamtcontainer über den <code>Key manager</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Phase 3: Deployment &amp; Aktivierung</h5>\n<ol class=\"fig-list\"><li><strong>Download:</strong> Das OEM-Backend übermittelt das aggregierte Container-Paket: <code>1&amp;2. A: Vehicle package</code>.\n</li><li><strong>In-Vehicle Execution:</strong> Verteilung an die lokalen UCM-Instanzen (bzw. UCM-Subordinates) zur Verifikation, Dekomprimierung und Vorbereitung der Zielpartitionen.\n</li><li><strong>Ergebnis-Rückmeldung:</strong> Nach Abschluss/Aktivierung meldet das Fahrzeug den Erfolgs- oder Fehlerstatus zurück an das Backend: <code>3. Activation(s) result(s)</code>.\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Dual-Signing-Modell (Kryptografische Kette):</strong>\n<ul class=\"fig-list\"><li>Entwickler/Integratoren müssen Backend-Pakete zwingend auf Integrator-Ebene signieren. \n</li><li>Das Fahrzeug selbst verifiziert primär die <code>OEM signature</code> des <code>Vehicle package</code>. Eine fehlerhafte oder abgelaufene Signatur im <code>Signed container</code> führt zum sofortigen Abbruch der UCM-Verifikationsphase vor jeglicher Datenextraktion.\n</li></ul>\n</li><li><strong>SWCL-Granularität &amp; Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li>Software darf nicht monolithisch gebündelt werden. Executables, Persistenzdaten und Konfigurationen müssen strikt nach Software Clustern (<code>SWCL</code>) getrennt sein.\n</li><li>Inter-SWCL-Abhängigkeiten müssen exakt in den ARXML-Paketmanifesten (<code>SWCL Package manifest</code>) deklariert werden, da UCM zyklische oder unaufgelöste Abhängigkeiten auf Knotenebene hart abweist.\n</li></ul>\n</li><li><strong>Persistenz- und Migrationsstrategie:</strong>\n<ul class=\"fig-list\"><li>Da <code>Persistency</code> explizit im Paket transportiert wird, müssen Entwickler Datenmigrationen (KVS/File Storage) über UCM-Lifecycle-Hooks (<code>Init</code>, <code>Update</code>, <code>Rollback</code>) deterministisch implementieren.\n</li></ul>\n</li><li><strong>Multi-Stack-Orchestrierung:</strong>\n<ul class=\"fig-list\"><li>UCM auf der Adaptive Platform fungiert im Fahrzeug als Orchestrator (<code>UCM Master</code>), muss jedoch Classic-AUTOSAR-Knoten (z. B. via DoIP/UDS auf Classic Bootloader) und Nicht-AUTOSAR-Systeme (COTS/IVI) im selben Transaktionskontext ansteuern können.\n</li><li>Entwickler müssen sicherstellen, dass Aktivierungsresultate (<code>Activation results</code>) synchronisiert gesammelt werden, um ein koordiniertes Rollback bei Fehlern auf Sub-Knoten auszulösen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c48298526e117d50", "releases": ["R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Systemisches Datenfluss- und Bereitstellungsdiagramm (End-to-End Packaging &amp; OTA Deployment Flow).\n</li><li><strong>Funktionale Einordnung:</strong> Spezifikation der AUTOSAR Adaptive Platform für <em>Update and Configuration Management</em> (UCM, Release R18-10). Es definiert die mehrstufige Lieferkette und den Verteilungsmechanismus von Software-Artefakten – von Multi-Vendor-Zulieferern über Tier-1-Integratoren und das OEM-Backend bis zur Zielarchitektur im Fahrzeug (Adaptive AUTOSAR, Classic AUTOSAR und Non-AUTOSAR/COTS).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Upstream-Entitäten (Lieferkette)</h5>\n<ul class=\"fig-list\"><li><strong>Vendor B / Vendor C:</strong> Bereitsteller nativer Artefakte (<code>Executable</code>, <code>Persistency</code>-Daten, <code>Configuration files</code>).\n</li><li><strong>Integrator (Tier-1):</strong> Führt Artefakte in einem Software Cluster (<code>SWCL</code>) zusammen.\n<ul class=\"fig-list\"><li><code>Packager</code>: Vom UCM-Entwickler bereitgestelltes Tooling zur Paketerstellung.\n</li><li><code>Integrator signing package for traceability</code>: Signiert das <code>Backend package</code> kryptografisch zur Absicherung der Zulieferkette.\n</li><li><code>Integrator repository</code>: Zwischenstation zur Übergabe an das OEM-Backend.\n</li></ul>\n</li><li><strong>Adaptive Autosar UCM developer (OEM, vendor):</strong> Spezifiziert/liefert das Packager-Werkzeug (<code>provide</code>).\n</li><li><strong>EE System engineer (OEM):</strong> Triggert und parametriert die Kampagnen im Backend (<code>@dev</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">OEM-Backend-Infrastruktur</h5>\n<ul class=\"fig-list\"><li><strong>Software catalog:</strong> Zentrales Repository für aufgenommene <code>Backend packages</code> (Integrator A repo &amp; Integrator B repo); liefert <code>Soft list</code> an die <code>VIN database</code> und übergibt <code>Software Package</code> sowie <code>Software Package manifest</code> an den <code>Vehicle packager</code>.\n</li><li><strong>VIN database:</strong> Speichert Fahrzeugkonfigurationen, aktuellen Softwarestand und liefert <code>Architecture</code>-Informationen an den <code>Campaign orchestrator</code>.\n</li><li><strong>Campaign orchestrator:</strong> Koordiniert Update-Kampagnen und übergibt Steuerungsdaten (<code>Campaign orchestration</code> und <code>UCM identifier</code>) an den <code>Vehicle packager</code>.\n</li><li><strong>Key manager:</strong> Verwaltet OEM-Root-Keys und Zertifikate zur Erzeugung der endgültigen Fahrzeugsignaturen für den <code>Vehicle packager</code>.\n</li><li><strong>Vehicle packager:</strong> Erzeugt das aggregierte <code>Vehicle package</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Datenstrukturen &amp; Paket-Hierarchie</h5>\n<ul class=\"fig-list\"><li><strong>SWCL (Software Cluster):</strong> Kleinste unabhängig aktualisierbare funktionale Einheit in Adaptive AUTOSAR.\n</li><li><strong>Backend package:</strong> Vom Integrator signierte Zwischenstufe des Pakets zur Bereitstellung an den OEM.\n</li><li><strong>Software Package:</strong> Einzelnes ECU-/Cluster-Update inkl. Binaries, Daten und <code>Software Package manifest</code>.\n</li><li><strong>Vehicle package:</strong> Aggregierter Container für das Gesamtfahrzeug, bestehend aus:\n<ul class=\"fig-list\"><li>Mehreren <code>Software Packages</code> (A, B, ...) mit Executables, Data und Manifesten.\n</li><li><code>Software Package manifest</code>.\n</li><li><code>Vehicle Package manifest</code>.\n</li><li><code>Signed container</code> mit übergeordneter <code>OEM signature</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">In-Vehicle Target-Architektur</h5>\n<ul class=\"fig-list\"><li><strong>Gateway / Telematics:</strong> Funkschnittstelle (<code>Internet ETSI</code> / Antenne) als OTA-Endpunkt.\n</li><li><strong>Zielknoten:</strong> Multi-ECU-Netzwerk mit <strong>Adaptive AUTOSAR</strong> (UCM-Host), <strong>Classic AUTOSAR</strong> und <strong>IVI / COTS (Non-AUTOSAR)</strong>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Phase 1: Upstream-Paketierung und Backend-Ingest</h5>\n<ol class=\"fig-list\"><li><strong>Artefakt-Erstellung:</strong> Vendors liefern Executables, Konfigurations- und Persistenzdaten an den Integrator.\n</li><li><strong>SWCL-Bündelung:</strong> Der Integrator packt die Artefakte via <code>Packager</code> in ein <code>Backend package</code> und signiert dieses zur Gewährleistung der Traceability.\n</li><li><strong>Katalogisierung:</strong> Bereitstellung in Integrator-Repos (A, B) und Übernahme in den <code>Software catalog</code> des OEM.\n</li></ol>\n<h5 class=\"fig-section-h5\">Phase 2: Zustandsermittlung &amp; Kampagnen-Orchestrierung</h5>\n<ul class=\"fig-list\"><li><strong>Abgleich-Szenario 1 (Vehicle-driven):</strong> Das Fahrzeug meldet proaktiv seinen Versionsstatus an die VIN-Datenbank (<code>1. Q: These are my versions statuses + VIN</code>).\n</li><li><strong>Abgleich-Szenario 2 (Backend-driven):</strong>\n<ul class=\"fig-list\"><li>Das Backend/Engineer fordert die Versionen an (<code>2. Q: Or what are your versions ? + VIN</code> bzw. <code>2. Q: Please upload versions list</code>).\n</li><li>Die VIN-Datenbank bzw. das Backend antwortet mit dem Sollstand (<code>2. A: My last versions for your VIN</code>).\n</li></ul>\n</li><li><strong>Kampagnenstart:</strong> Der EE System Engineer stößt die Kampagnenorchestrierung an. Der <code>Campaign orchestrator</code> verknüpft Architekturvorgaben der VIN-Datenbank mit den freigegebenen Softwareständen aus dem Katalog und übergibt die Orchestrierungsdaten inklusive <code>UCM identifier</code> an den Vehicle Packager.\n</li></ul>\n<h5 class=\"fig-section-h5\">Phase 3: Fahrzeugpaketierung &amp; Auslieferung</h5>\n<ol class=\"fig-list\"><li><strong>Paket-Assemblierung:</strong> Der <code>Vehicle packager</code> kombiniert <code>Software Packages</code>, <code>Software Package manifest</code> und Schlüsselinformationen des <code>Key manager</code> unter Berücksichtigung des Ziel-<code>UCM identifier</code> zu einem signierten <code>Vehicle package</code>.\n</li><li><strong>OTA-Übertragung:</strong> Das generierte <code>Vehicle package</code> wird an das Fahrzeug übertragen (<code>1&amp;2. A: Vehicle package</code>).\n</li><li><strong>Aktivierungsrückmeldung:</strong> Nach Installation und Aktivierung auf den Zielknoten (Adaptive AUTOSAR, Classic AUTOSAR, IVI/COTS) meldet das Fahrzeug das Ergebnis zurück an das OEM-Backend (<code>3. Activation(s) result(s)</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Dual-Signing-Modell (Kryptografische Kette):</strong>\n<ul class=\"fig-list\"><li>Entwickler/Integratoren müssen Backend-Pakete zwingend auf Integrator-Ebene signieren. \n</li><li>Das Fahrzeug selbst verifiziert primär die <code>OEM signature</code> des <code>Vehicle package</code>. Eine fehlerhafte oder abgelaufene Signatur im <code>Signed container</code> führt zum sofortigen Abbruch der UCM-Verifikationsphase vor jeglicher Datenextraktion.\n</li></ul>\n</li><li><strong>SWCL-Granularität &amp; Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li>Software darf nicht monolithisch gebündelt werden. Executables, Persistenzdaten und Konfigurationen müssen strikt nach Software Clustern (<code>SWCL</code>) getrennt sein.\n</li><li>Inter-SWCL-Abhängigkeiten müssen exakt in den ARXML-Paketmanifesten (<code>SWCL Package manifest</code>) deklariert werden, da UCM zyklische oder unaufgelöste Abhängigkeiten auf Knotenebene hart abweist.\n</li></ul>\n</li><li><strong>Persistenz- und Migrationsstrategie:</strong>\n<ul class=\"fig-list\"><li>Da <code>Persistency</code> explizit im Paket transportiert wird, müssen Entwickler Datenmigrationen (KVS/File Storage) über UCM-Lifecycle-Hooks (<code>Init</code>, <code>Update</code>, <code>Rollback</code>) deterministisch implementieren.\n</li></ul>\n</li><li><strong>Multi-Stack-Orchestrierung:</strong>\n<ul class=\"fig-list\"><li>UCM auf der Adaptive Platform fungiert im Fahrzeug als Orchestrator (<code>UCM Master</code>), muss jedoch Classic-AUTOSAR-Knoten (z. B. via DoIP/UDS auf Classic Bootloader) und Nicht-AUTOSAR-Systeme (COTS/IVI) im selben Transaktionskontext ansteuern können.\n</li><li>Entwickler müssen sicherstellen, dass Aktivierungsresultate (<code>Activation results</code>) synchronisiert gesammelt werden, um ein koordiniertes Rollback bei Fehlern auf Sub-Knoten auszulösen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-c621420d06746c7c", "to": "FIG-c48298526e117d50", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Software Package Manifest:</strong> Die Manifest-Bezeichnung am Übergang vom Software catalog zum Vehicle packager wurde von <code>SWCL Package manifest</code> zu <code>Software Package manifest</code> generalisiert.\n</li><li><strong>Orchestrierungs-Schnittstelle:</strong> Die Übergabe vom Campaign orchestrator an den Vehicle packager wurde neben <code>Campaign orchestration</code> um den Parameter/Bezeichner <code>UCM identifier</code> erweitert.\n</li></ul>"}]};
